// 一个完整的泛型 Result 设计
public sealed interface Result<T> permits Result.Success, Result.Failure {

    record Success<T>(T data) implements Result<T> { }

    record Failure<T>(String message, Throwable cause) implements Result<T> { }

    // 成功时转换，失败时保持不变（PECS：消费 T，生产 R）
    default <R> Result<R> map(Function<? super T, ? extends R> mapper) {
        return switch (this) {
            case Success<T> s -> new Success<>(mapper.apply(s.data()));
            case Failure<T> f -> new Failure<>(f.message(), f.cause());
        };
    }

    // 取值，失败时用默认值（返回值不能用通配符）
    default T getOrElse(T defaultValue) {
        return switch (this) {
            case Success<T> s -> s.data();
            case Failure<T> f -> defaultValue;
        };
    }

    // 失败时的副作用（Consumer 只消费，用 super）
    default Result<T> onFailure(Consumer<? super Throwable> handler) {
        if (this instanceof Failure<T> f && f.cause() != null) {
            handler.accept(f.cause());
        }
        return this;
    }

    static <T> Result<T> ok(T data) { return new Success<>(data); }
    static <T> Result<T> fail(String msg, Throwable cause) { return new Failure<>(msg, cause); }
}

